                        )
                    )
                    root_cmd(
                        'salt-call {0}'.format(start_action),
                        tty, sudo, **kwargs
                    )
                    log.info(
                        'Finished executing {0} on the salt-minion'.format(
                            start_action
                        )
                    )
            # Fire deploy action
            event = salt.utils.event.SaltEvent('master', sock_dir)
            try:
                event.fire_event(
                    '{0} has been created at {1}'.format(name, host),
