		conn.commit()
		cursor.close()
	except Exception,e:
		cursor.close()
		return jsonify({"result_code":"-1", "result_msg":"error", "p_id":0})
	return jsonify({"result_code":"0", "result_msg":"success", "p_id":p_id})

